#include <iostream>
#include <vector>
#include <cstring>
using namespace std;

const int MOD = 1e9 + 7;

class Modular {
public:
    int m;

    Modular(int m) : m(m) {}
    Modular(long long m) : m((int)m) {
        if (this->m != m) throw invalid_argument("invalid modulus");
    }
    Modular(double m) : m((int)m) {
        if (this->m != m) throw invalid_argument("invalid modulus");
    }

    int valueOf(int x) {
        x %= m;
        if (x < 0) x += m;
        return x;
    }

    int valueOf(long long x) {
        x %= m;
        if (x < 0) x += m;
        return (int)x;
    }

    int mul(int x, int y) {
        return valueOf((long long)x * y);
    }

    int plus(int x, int y) {
        return valueOf(x + y);
    }
};

class FastInput {
private:
    static const int BUFSIZE = 1 << 13;
    char buf[BUFSIZE];
    int bufLen = 0;
    int bufOffset = 0;
    int next = -1;

    int read() {
        if (bufLen == bufOffset) {
            bufOffset = 0;
            bufLen = fread(buf, 1, BUFSIZE, stdin);
            if (bufLen <= 0) return -1;
        }
        return buf[bufOffset++];
    }

public:
    void skipBlank() {
        while (next >= 0 && next <= 32) next = read();
    }

    int readInt() {
        int sign = 1;
        skipBlank();
        if (next == '+' || next == '-') {
            sign = next == '+' ? 1 : -1;
            next = read();
        }
        int val = 0;
        if (sign == 1) {
            while (next >= '0' && next <= '9') {
                val = val * 10 + next - '0';
                next = read();
            }
        } else {
            while (next >= '0' && next <= '9') {
                val = val * 10 - next + '0';
                next = read();
            }
        }
        return val;
    }
};

class FastOutput {
private:
    static const int BUFSIZE = 1 << 20;
    char buf[BUFSIZE];
    int bufLen = 0;

public:
    void println(int c) {
        char numBuf[12];
        int len = sprintf(numBuf, "%d\n", c);
        for (int i = 0; i < len; i++) {
            if (bufLen == BUFSIZE) flush();
            buf[bufLen++] = numBuf[i];
        }
    }

    void flush() {
        fwrite(buf, 1, bufLen, stdout);
        bufLen = 0;
    }

    ~FastOutput() {
        flush();
    }
};

class G2PlaylistForPolycarpHardVersion {
public:
    void solve(int testNumber, FastInput& in, FastOutput& out) {
        Modular mod(MOD);

        int n = in.readInt();
        int m = in.readInt();
        vector<vector<int>> musics(n, vector<int>(2));
        vector<int> cnts(4, 0);
        for (int i = 0; i < n; i++) {
            musics[i][0] = in.readInt();
            musics[i][1] = in.readInt();
            cnts[musics[i][1]]++;
        }

        int c1 = cnts[1];
        int c2 = cnts[2];
        int c3 = cnts[3];

        vector<vector<vector<vector<int>>>> comp(c1 + 1,
            vector<vector<vector<int>>>(c2 + 1,
                vector<vector<int>>(c3 + 1, vector<int>(4, 0))));

        for (int i = 0; i <= c1; i++) {
            for (int j = 0; j <= c2; j++) {
                for (int k = 0; k <= c3; k++) {
                    for (int t = 0; t < 4; t++) {
                        if (i == 0 && j == 0 && k == 0) {
                            comp[i][j][k][t] = 1;
                            continue;
                        }
                        if (i > 0 && t != 1) {
                            comp[i][j][k][t] = mod.plus(comp[i][j][k][t], mod.mul(comp[i - 1][j][k][1], i));
                        }
                        if (j > 0 && t != 2) {
                            comp[i][j][k][t] = mod.plus(comp[i][j][k][t], mod.mul(comp[i][j - 1][k][2], j));
                        }
                        if (k > 0 && t != 3) {
                            comp[i][j][k][t] = mod.plus(comp[i][j][k][t], mod.mul(comp[i][j][k - 1][3], k));
                        }
                    }
                }
            }
        }

        vector<vector<vector<vector<int>>>> last(c1 + 1,
            vector<vector<vector<int>>>(c2 + 1,
                vector<vector<int>>(c3 + 1, vector<int>(m + 1, 0))));
        vector<vector<vector<vector<int>>>> next(c1 + 1,
            vector<vector<vector<int>>>(c2 + 1,
                vector<vector<int>>(c3 + 1, vector<int>(m + 1, 0))));

        last[0][0][0][0] = 1;
        int t1 = 0, t2 = 0, t3 = 0;
        for (int i = 0; i < n; i++) {
            int m1 = musics[i][1];
            int m0 = musics[i][0];
            if (m1 == 1) t1++;
            else if (m1 == 2) t2++;
            else t3++;

            for (int a = 0; a <= t1; a++) {
                for (int b = 0; b <= t2; b++) {
                    for (int c = 0; c <= t3; c++) {
                        for (int t = 0; t <= m; t++) {
                            next[a][b][c][t] = last[a][b][c][t];
                            if (t < m0) continue;
                            if (m1 == 1 && a > 0) {
                                next[a][b][c][t] = mod.plus(next[a][b][c][t], last[a - 1][b][c][t - m0]);
                            } else if (m1 == 2 && b > 0) {
                                next[a][b][c][t] = mod.plus(next[a][b][c][t], last[a][b - 1][c][t - m0]);
                            } else if (m1 == 3 && c > 0) {
                                next[a][b][c][t] = mod.plus(next[a][b][c][t], last[a][b][c - 1][t - m0]);
                            }
                        }
                    }
                }
            }

            swap(last, next);
        }

        int ans = 0;
        for (int i = 0; i <= c1; i++) {
            for (int j = 0; j <= c2; j++) {
                for (int k = 0; k <= c3; k++) {
                    ans = mod.plus(ans, mod.mul(last[i][j][k][m], comp[i][j][k][0]));
                }
            }
        }

        out.println(ans);
    }
};

int main() {
    FastInput in;
    FastOutput out;
    G2PlaylistForPolycarpHardVersion solver;
    solver.solve(1, in, out);
    out.flush();
    return 0;
}

